round_even_smoke_source:
#include "../../src/coremath_pow.h"
#include <stdio.h>
int main(void) {
  volatile double inputs[] = {0.5, 1.5, 2.5, -0.5, -1.5, -2.5, 2147483648.5};
  const uint64_t expected[] = {0x0000000000000000ULL, 0x4000000000000000ULL,
      0x4000000000000000ULL, 0x8000000000000000ULL, 0xc000000000000000ULL,
      0xc000000000000000ULL, 0x41e0000000000000ULL};
  int failures = 0;
  for (unsigned i = 0; i < sizeof(inputs) / sizeof(inputs[0]); ++i) {
    union { double f; uint64_t bits; } result = {.f = roundeven_finite(inputs[i])};
    if (result.bits != expected[i]) {
      printf("round-even(%g): expected %016llx, found %016llx\n", inputs[i],
          (unsigned long long)expected[i], (unsigned long long)result.bits);
      ++failures;
    }
  }
  printf("round-even smoke: %u cases, %d failures\n", (unsigned)(sizeof(inputs) / sizeof(inputs[0])), failures);
  return failures != 0;
}

wasi_launcher_source:
import { readFile } from 'node:fs/promises';
import { WASI } from 'node:wasi';

const artifact = process.argv[2];
if (!artifact) throw new Error('WASI artifact path required');
const wasi = new WASI({
  version: 'preview1',
  args: [artifact],
  env: {},
  preopens: {},
  returnOnExit: true,
});
const module = await WebAssembly.compile(await readFile(artifact));
const instance = await WebAssembly.instantiate(module, wasi.getImportObject());
process.exitCode = wasi.start(instance);

